36: async function requestApi<T>(path: string, accessToken: string | null, setAccessToken: (value: string | null) => void, options: ApiOptions = {}): Promise<T> {
37:   if (!API) throw new Error('Set NEXT_PUBLIC_API_URL in admin/.env.local before starting the portal.');
38:   const execute = (token: string | null) => {
39:     const headers = new Headers();
40:     if (token) headers.set('Authorization', `Bearer ${token}`);
41:     const isForm = typeof FormData !== 'undefined' && options.body instanceof FormData;
42:     if (options.body !== undefined && !isForm) headers.set('Content-Type', 'application/json');
43:     return fetch(`${API}${path}`, {
44:       method: options.method ?? (options.body === undefined ? 'GET' : 'POST'),
45:       headers,
46:       credentials: 'include',
47:       body: options.body === undefined ? undefined : isForm ? options.body as FormData : JSON.stringify(options.body),
48:       cache: 'no-store',
49:     });
50:   };
51:   let response = await execute(accessToken);
52:   if (response.status === 401 && accessToken && !path.startsWith('/auth/')) {
53:     const refresh = await fetch(`${API}/auth/refresh`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: '{}' });
54:     if (refresh.ok) {
55:       const renewed = await refresh.json() as { access_token: string };
56:       setAccessToken(renewed.access_token);
57:       response = await execute(renewed.access_token);
58:     } else {
59:       setAccessToken(null);
60:       throw new Error('Your session expired. Sign in again.');
61:     }
62:   }
63:   if (!response.ok) {
64:     let detail = `Request failed (${response.status})`;
65:     try { const body = await response.json() as { detail?: unknown }; if (typeof body.detail === 'string') detail = body.detail; } catch { /* Use the status message. */ }
66:     throw new Error(detail);
67:   }
68:   if (options.responseType === 'blob') return await response.blob() as T;
69:   if (response.status === 204) return undefined as T;
70:   return await response.json() as T;
71: }
